#include <deque>
#include <iostream>
#include <string>

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        std::deque<char> letters;
        for (char c : line) {
            if (c >= 'a' && c <= 'z') {
                letters.push_back(c);
            } else if (c >= 'A' && c <= 'Z') {
                letters.push_back(static_cast<char>(c - 'A' + 'a'));
            }
        }
        bool palindrome = true;
        while (letters.size() > 1) {
            if (letters.front() != letters.back()) {
                palindrome = false;
                break;
            }
            letters.pop_front();
            letters.pop_back();
        }
        std::cout << (palindrome ? "да" : "нет") << '\n';
    }
    return 0;
}

