#include <deque>
#include <iostream>
#include <string>

int main() {
    std::string first;
    if (!(std::cin >> first)) {
        return 0;
    }
    std::deque<std::string> playlist = {first};
    std::size_t current = 0;
    std::string command;
    while (std::cin >> command) {
        if (command == "add_back" || command == "add_front") {
            std::string name;
            std::cin >> name;
            if (command == "add_back") {
                playlist.push_back(name);
            } else {
                playlist.push_front(name);
            }
        } else if (command == "next") {
            if (current + 1 < playlist.size()) {
                current++;
            }
        } else if (command == "prev") {
            if (current > 0) {
                current--;
            }
        } else if (command == "now") {
            std::cout << playlist[current] << '\n';
        }
    }
    return 0;
}

